using Xunit;

namespace Insurance.UnitTest.Features.Pricing;

public class PricingAcceptanceTests
{
    // Rider of age gets a motorcycle quote
    [Fact]
    public void Rider_of_age_gets_a_motorcycle_quote()
    {
        var useCase = new RequestQuote(new InMemoryQuotes());

        var result = useCase.Handle(new QuoteRequest(Age: 25, Vehicle: "motorcycle"));

        Assert.True(result.Accepted);
        Assert.Equal(480.50m, result.Premium);
    }
}

