namespace Insurance.Application;

public record QuoteRequest(int Age, string Vehicle);
public record QuoteResult(bool Accepted, decimal? Premium, string? RejectionReason);
public interface IQuotes { }

public class RequestQuote
{
    public RequestQuote(IQuotes quotes) { }
    public QuoteResult Handle(QuoteRequest request) => new QuoteResult(false, null, null);
}
